    assert(maxAlternatingLength(2, 0, 0) == 1);      // Two chocolates, no non-chocolate -> can only use one
    assert(maxAlternatingLength(2, 1, 0) == 3);      // C N C
    assert(maxAlternatingLength(3, 1, 0) == 3);      // Have more chocolate than needed
    assert(maxAlternatingLength(3, 2, 1) == 5);      // C N C N C
    assert(maxAlternatingLength(5, 10, 10) == 9);    // 5 chocolates, lots of non-chocolate -> 2*5-1=9
    assert(maxAlternatingLength(1, 1, 0) == 1);      // Only one chocolate, extra non-chocolate unusable
    assert(maxAlternatingLength(0, 5, 5) == 0);      // No chocolate at all
    assert(maxAlternatingLength(0, 0, 0) == 0);      // Nothing
